class MyQueue:
    def __init__(self):
        self.inbox = []
        self.outbox = []
    def _shift(self):
        if not self.outbox:
            while self.inbox:
                self.outbox.append(self.inbox.pop())
    def push(self, x):
        self.inbox.append(x)
    def pop(self):
        self._shift()
        return self.outbox.pop() if self.outbox else -1
    def peek(self):
        self._shift()
        return self.outbox[-1] if self.outbox else -1

